-- =========================
-- Catalogo de cidades (IBGE): municipios e distritos, com UF e codigo IBGE. Somente leitura (sem CRUD na API);
-- usado pelas rotas e pelas cidades extras da Agenda. O distrito e um item distinto do municipio (tipo DISTRITO,
-- municipio_nome = municipio pai). nome_busca = nome (+ municipio, no distrito) em minusculo e sem acento, para a
-- busca sem acento e sem diferenciar maiuscula sem depender da extensao unaccent.
-- =========================
CREATE TABLE cidades (
    id BIGSERIAL PRIMARY KEY,
    nome VARCHAR(255) NOT NULL,
    uf VARCHAR(2) NOT NULL,
    ibge VARCHAR(9) NOT NULL,
    tipo VARCHAR(10) NOT NULL,
    municipio_nome VARCHAR(255),
    nome_busca VARCHAR(512) NOT NULL,
    CONSTRAINT uq_cidades_ibge UNIQUE (ibge),
    CONSTRAINT ck_cidades_tipo CHECK (tipo IN ('MUNICIPIO', 'DISTRITO')),
    CONSTRAINT ck_cidades_municipio_nome CHECK ((tipo = 'DISTRITO' AND municipio_nome IS NOT NULL) OR (tipo = 'MUNICIPIO' AND municipio_nome IS NULL))
);

CREATE INDEX idx_cidades_uf ON cidades (uf);
CREATE INDEX idx_cidades_nome_busca ON cidades (nome_busca);

